use axum::{routing::get, Router, State};

async fn fallback(_: State<&'static str>) -> &'static str {
    "fallback"
}

async fn not_found(_: State<&'static str>) -> (axum::http::StatusCode, &'static str) {
    (axum::http::StatusCode::NOT_FOUND, "not found")
}

#[tokio::main]
async fn main() {
    let state = "foo";

    let app: Router = Router::new()
        .fallback(get(fallback).fallback(not_found))
        .with_state(state);

    let server = axum::Server::bind(&"127.0.0.1:0".parse().unwrap());
    let addr = server.local_addr();
    tokio::spawn(async move {
        server.serve(app.into_make_service()).await.unwrap();
    });

    // GET request -> fallback
    let client = hyper::Client::new();
    let res = client
        .get(hyper::Uri::try_from(&format!("http://{addr}/anything")).unwrap())
        .await
        .unwrap();
    assert_eq!(res.status(), 200);
    let body = hyper::body::to_bytes(res.into_body()).await.unwrap();
    assert_eq!(&body[..], b"fallback");

    // POST request -> not_found
    let res = client
        .post(hyper::Uri::try_from(&format!("http://{addr}/anything")).unwrap())
        .body(hyper::Body::empty())
        .await
        .unwrap();
    assert_eq!(res.status(), 404);
    let body = hyper::body::to_bytes(res.into_body()).await.unwrap();
    assert_eq!(&body[..], b"not found");

    println!("all checks passed");
}

